  return O + f*d*s + vec3(0., (.5 + .22*d)*4.*s*(1. - s), 0.); }
    void main(){ float u = uTime - aT; if (u < 0. || uTime - aR > .12){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float h = min(u, aR - aT), d = length(uRuntimeEndpoint.xz);
      float s = position.x*.5 + .5;
      vec3 P = arcP(aO, aY, d, s) + vec3(0., .06, 0.), T = normalize(arcP(aO, aY, d, min(s + .01, 1.)) - arcP(aO, aY, d, max(s - .01, 0.)));
