layers.fragment:
uniform float uTime; uniform vec3 uGold, uOrange; varying float vS, vY, vF, vD;
    void main(){ float dash = smoothstep(.35, .5, fract(vS*vD*2.2 - uTime*1.8));            // fine dashes running forward
      float f = exp(-vY*vY*4.)*mix(.35, 1., dash)*smoothstep(0., .08, vS)*vF;
      vec3 o = mix(uOrange, uGold, .5)*f*.7;
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }

